```ts
// src/session/types.ts
export interface Session {
  transcript: string;
  documentPath?: string;
}

export interface SessionStore {
  get(userId: number): Promise<Session>;
  set(userId: number, session: Session): Promise<void>;
  clear(userId: number): Promise<void>;
}
